import {journey} from './journey.js';
import {berPotentialCard,berBaselineForm} from './ber-potential.js';
import {landing,finance,fundingPreview,berPanel} from './features.js';
import {icon} from './icons.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euros=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const range=a=>!a||a.some(n=>n===null)?'Quote required':a[0]===a[1]?euros(a[0]):`${euros(a[0])}–${euros(a[1])}`;
const compact=range;
const grantCost=p=>euros(p.funding?.breakdowns?.beh.referenceGrantSubtotal??0);
const netCost=p=>euros(p.funding?.breakdowns?.beh.referenceNetSubtotal??0);
const date=s=>new Date(s).toLocaleDateString('en-IE',{day:'numeric',month:'short',year:'numeric'});
const type=t=>({semi:'Semi-detached',detached:'Detached house',terrace:'Mid-terrace',apartment:'Apartment'}[t]);
const scenarioNames={comfort:'Comfort first',balanced:'Heat-pump ready',complete:'Whole-home upgrade'};
const scenarioDescriptions={comfort:'Start with the fabric. A warmer, healthier home in manageable stages.',balanced:'Improve the fabric, then prepare for efficient, low-carbon heating.',complete:'Take the whole-home view, with insulation, heating and solar electricity.'};
const state={session:null,profiles:[],profile:null,page:'overview',messages:[],reports:[],sources:null,admin:null,busy:false,drafts:{}};
let toastTimer,lastFocus;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
async function api(url,method='GET',data){const r=await fetch(`/api${url}`,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},...(data!==undefined?{body:JSON.stringify(data)}:{})});let body;try{body=await r.json();}catch{throw new Error('The server returned an unexpected response.');}if(!r.ok){if(r.status===401&&state.session?.user){state.session.user=null;render();}throw new Error(body.error||'Something went wrong. Please retry.');}return body;}
async function loadProfiles(){const previous=state.profile?.id||localStorage.getItem('rf-home');state.profiles=(await api('/profiles')).profiles;state.profile=state.profiles.find(p=>p.id===previous)||state.profiles[0]||null;if(state.profile)localStorage.setItem('rf-home',state.profile.id);}
async function loadPage(page){state.page=page;state.messages=[];if(page==='interview'&&state.profile)state.messages=(await api(`/profiles/${state.profile.id}/messages`)).messages;if(page==='reports')state.reports=(await api('/reports')).reports;if(page==='sources')state.sources=await api('/sources');if(page==='governance')state.admin=await api('/admin');render();}
function go(page){if(location.hash===`#${page}`)loadPage(page).catch(e=>toast(e.message));else location.hash=page;}
function button(action,label,kind='primary',ico='arrow',extra=''){return `<button class="${kind}-btn" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;}
function selector(){return `<div class="select-wrap"><select class="home-select" id="home-select" aria-label="Choose a home">${state.profiles.map(p=>`<option value="${p.id}" ${p.id===state.profile?.id?'selected':''}>${esc(p.data.name)}</option>`).join('')}</select>${icon('down')}</div>`;}
function logo(){return `<div class="brand"><img src="/favicon.svg" alt=""/><div><strong>Retrofit<br>Pathfinder</strong><small>A clearer way home</small></div></div>`;}
function footnote(){return `<div class="footnote">${icon('shield')}<span>Independent of SEAI. A planning guide for qualified assessment. Costs are illustrative, grants are conditional, and every home is different. SEAI grant catalogue checked 9 September 2026.</span></div>`;}
function pageHead(eyebrow,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action||(state.profile?selector():'')}</div>`;}
function ribbon(){const p=state.profile.data;return `<div class="profile-ribbon"><div class="home-square">${icon('home')}</div><div class="ribbon-name"><select id="ribbon-home-select" aria-label="Switch home profile">${state.profiles.map(h=>`<option value="${h.id}" ${h.id===state.profile.id?'selected':''}>${esc(h.data.name)}</option>`).join('')}</select><small>${icon('pin').replace('class="icon','class="icon pin-small')} ${esc(p.county)}, Ireland ${p.synthetic?'· Example home':''}</small></div><div class="ribbon-facts"><div class="fact"><small>Home type</small><strong>${type(p.type)}</strong></div><div class="fact"><small>Built</small><strong>${p.year}</strong></div><div class="fact"><small>Current BER</small><strong class="ber ${p.ber.startsWith('A')||p.ber.startsWith('B')?'green':''}">${p.ber==='unknown'?'Unknown':p.ber}</strong></div><div class="fact"><small>Floor area</small><strong>${p.area} m²</strong></div></div>${button('edit-home','Edit profile','outline','edit')}</div>`;}
function budgetNotice(plan){if(plan.costIncomplete)return `<div class="notice"><p>Partial benchmark only: assessment and other quote-required items are excluded. The complete project cost and budget fit are not yet known.</p></div>`;return plan.overBudget?`<div class="notice">${icon('info')}<p>The upper estimate exceeds your ${euros(plan.budget)} budget. Explore a smaller first phase and get itemised quotations before committing. Support is not guaranteed.</p></div>`:'';}
function steps(plan,preview=false){return `<div class="pathway-list">${(preview?plan.steps.slice(0,4):plan.steps).map((s,i)=>`<article class="step ${i===0?'first':''}"><span class="step-num">${String(i+1).padStart(2,'0')}</span><div class="step-content"><div class="step-phase">${s.phase}</div><div class="step-heading"><h3>${esc(s.title)}</h3>${i===0?'<span class="pill">Your next step</span>':''}</div><p>${esc(preview?{survey:'Get the right evidence before making the big decisions.',moisture:'Check the cause before you cover it with insulation.',ventilation:'Make a healthier home part of your fabric upgrade.',attic:'Keep more of your warmth where it belongs.',walls:'Confirm the right approach for your walls.'}[s.id]||s.why:s.why)}</p><div class="step-meta"><span>${range(s.cost)}</span><span>See BEH / OSS grant and net-cost tables</span></div>${preview?'':`<details class="step-details"><summary>Dependencies & contractor checks</summary><div class="depends">${icon('route')} ${s.depends.length?`After: ${s.depends.map(k=>esc(plan.steps.find(m=>m.id===k)?.title||k)).join(' · ')}`:'Start with this assessment. No prior measure required.'}</div><ul>${s.checks.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>${s.source?`<a href="#sources">View the dated SEAI evidence ${icon('arrow')}</a>`:''}</details>`}</div></article>`).join('')}</div>`;}
function nextQuestions(plan){return `<div class="next-card"><h3>${icon('chat')} A few things to find out</h3>${plan.questions.slice(0,3).map(q=>`<button class="question-link" data-action="question" data-key="${q.key}"><span class="question-bullet"></span>${esc(q.title)}${icon('chevron')}</button>`).join('')||'<p class="tiny">Bring your evidence to a qualified adviser to verify the details.</p>'}</div>`;}
function overview(){if(!state.profile)return emptyHome();const p=state.profile.data,plan=state.profile.plan;return `<section class="hero"><div><div class="eyebrow"><span class="dot"></span>Small steps. Lasting difference.</div><h1>A warmer home.<br><em>A clearer path.</em></h1><p>You don’t have to figure it all out at once. Let’s find the right upgrades, in the right order, for your home.</p><div class="hero-buttons">${button('navigate-interview','Continue your home interview','primary','chat')}<button class="text-btn" data-action="navigate-pathway">View your pathway ${icon('arrow')}</button></div></div><div class="hero-visual"><img src="/house.svg" alt="Illustration of an Irish home with roof insulation, solar panels and a green garden"/><span class="visual-tag">${icon('leaf')} MADE FOR IRISH HOMES</span><div class="visual-label">${icon('shield')}Better decisions start with your whole home.</div></div></section>${ribbon()}${berPotentialCard(plan)}<div class="mt20"><button class="outline-btn" data-action="navigate-funding">Grants, upfront costs & what you pay →</button></div><div class="stats"><div class="stat"><div class="stat-icon">${icon('route')}</div><div class="stat-label">Your personalised pathway</div><div class="stat-value">${plan.steps.length} considered steps</div><small>Designed around your home’s dependencies</small></div><div class="stat"><div class="stat-icon">${icon('euro')}</div><div class="stat-label">Priced measures subtotal</div><div class="stat-value">${compact(plan.total)}</div><small>Excludes quote-required items · no contingency added</small></div><div class="stat"><div class="stat-icon">${icon('leaf')}</div><div class="stat-label">Published grant reference</div><div class="stat-value green">${grantCost(plan)}</div><small>${plan.support?'Subject to eligibility · award could be €0':'Resolve eligibility and source review first'}</small></div></div><div class="dashboard-lower"><section><div class="section-heading"><div><h2>Your path to a better home</h2><p>${scenarioNames[plan.scenario]} · A sensible order, with room to adapt.</p></div><button class="text-btn" data-action="navigate-pathway">Full pathway ${icon('arrow')}</button></div>${steps(plan,true)}</section><aside class="dashboard-aside"><div class="insight">${icon('spark')}<div class="eyebrow">WHY THE ORDER MATTERS</div><h3>Keep the warmth in.<br>Then rethink the heating.</h3><p>Improving your home’s fabric first can reduce the heating it needs. A properly assessed heat pump can then be sized for your improved home.</p><button class="text-btn" data-action="navigate-compare">Explore your options ${icon('arrow')}</button></div>${nextQuestions(plan)}</aside></div>${footnote()}`;}
function pathway(){if(!state.profile)return emptyHome();const plan=state.profile.plan;return `${pageHead('YOUR RETROFIT ROADMAP','The right steps. In the right order.','A provisional pathway shaped around your home, budget and priorities.')}${ribbon()}${berPotentialCard(plan)}${state.profile.deletion_requested_at?deletionNotice():''}<div class="dashboard-lower"><section><div class="section-heading"><div><h2>${scenarioNames[plan.scenario]}</h2><p>${plan.steps.length} ordered measures · Technical assessment required</p></div><span class="pill">Planning stage</span></div>${steps(plan)}</section><aside><div class="brief-summary"><div class="card"><div class="eyebrow">YOUR PLANNING ENVELOPE</div><h2>Make room for the unknowns.</h2><div class="cost-line"><span>SEAI median subtotal</span><strong>${compact(plan.gross)}</strong></div><div class="cost-line"><span>Contingency · not added</span><strong>${compact(plan.contingency)}</strong></div><div class="cost-line"><span>Published grant reference</span><strong>${grantCost(plan)}</strong></div><div class="cost-line total"><span>Net reference if eligible</span><strong>${netCost(plan)}</strong></div><p class="tiny mt20">Net reference uses published grant rates, even while eligibility is being checked. See the separate eligibility status on the funding page.</p>${button('generate-report','Save contractor brief','primary','file','class="full"')}<div class="mt20"><button class="text-btn" data-action="navigate-compare">Compare all three scenarios ${icon('arrow')}</button></div></div>${budgetNotice(plan)}${nextQuestions(plan)}</div></aside></div><div class="card mt20"><h3>What this pathway assumes</h3>${plan.assumptions.map(a=>`<p class="tiny">${esc(a)}</p>`).join('')}</div>${fundingPreview(state.profile.plan)}${footnote()}`;}
function compare(){if(!state.profile)return emptyHome();const scenarios=state.profile.scenarios;return `${pageHead('EXPLORE YOUR OPTIONS','One home. Different ways forward.','Compare the scope and planning costs before choosing the pace that suits you.')}<div class="notice info">${icon('info')}<p>All scenarios start with assessment and healthy ventilation. Potential BER is an illustrative range only where evidence is sufficient; bill savings are not predicted. Matched measures default to exact SEAI 2025 medians. Quote-required items are excluded from the subtotal; the full project cost is not yet known.</p></div><div class="scenario-grid">${scenarios.map(s=>`<section class="scenario-card ${s.scenario===state.profile.data.goal?'selected':''}">${s.scenario===state.profile.data.goal?'<span class="recommend-label">YOUR SELECTED PATHWAY</span>':''}${icon({comfort:'home',balanced:'leaf',complete:'sun'}[s.scenario])}<h2>${scenarioNames[s.scenario]}</h2><p>${scenarioDescriptions[s.scenario]}</p>${berPotentialCard(s,true)}<small>Priced measures subtotal, before supports</small><div class="scenario-price">${compact(s.total)}</div><small>Excludes unpriced items; no contingency added</small><ul>${s.steps.map(m=>`<li>${icon('check')}${esc(m.title)}</li>`).join('')}</ul><div class="cost-line"><span>Grant reference</span><strong>${grantCost(s)}</strong></div><div class="cost-line"><span>Net reference if eligible</span><strong>${netCost(s)}</strong></div><p class="tiny">${s.overBudget?'Upper estimate exceeds your budget.':'Full budget fit unknown until quote-required items are priced.'}</p>${button('select-scenario',s.scenario===state.profile.data.goal?'View this pathway':'Choose this pathway',s.scenario===state.profile.data.goal?'primary':'outline','arrow',`data-scenario="${s.scenario}"`)}</section>`).join('')}</div><div class="card"><h2>Look beyond the headline cost</h2><div class="scroll-table"><table class="compare-table"><thead><tr><th>WHAT TO CONSIDER</th>${scenarios.map(s=>`<th>${scenarioNames[s.scenario].toUpperCase()}</th>`).join('')}</tr></thead><tbody><tr><td>Primary focus</td><td>Comfort & heat retention</td><td>Fabric & heating transition</td><td>Fabric, heating & generation</td></tr><tr><td>Heat pump</td><td>Deferred for later assessment</td><td>Conditional on heat-loss readiness</td><td>Conditional on heat-loss readiness</td></tr><tr><td>Solar PV</td><td>Outside current scope</td><td>Outside current scope</td><td>4 kWp example; roof and electrical checks</td></tr><tr><td>BER outcome</td><td colspan="3">Qualified assessment required. No rating improvement is guaranteed; see each scenario’s evidence-gated illustration.</td></tr><tr><td>Support route</td><td colspan="3">Individual grants only in these figures. Ask a One Stop Shop for a separate managed-package assessment; do not add its grants to these.</td></tr></tbody></table></div></div>${finance(state.profile.plan)}${footnote()}`;}
function emptyHome(){return `${pageHead('YOUR HOME ENERGY JOURNEY','Every home has a starting point.','Tell us a little about yours. We’ll help make the next steps clearer.')}<div class="empty card">${icon('home')}<h2>Let’s get to know your home</h2><p>Create a profile to start your interview, compare pathways and save a contractor-ready brief.</p>${state.session.user.role==='homeowner'?button('new-home','Add your home','primary','plus'):'<p>An administrator can assign a homeowner profile to your adviser account.</p>'}</div>`;}
function deletionNotice(){return `<div class="notice">${icon('trash')}<p>This home has a pending deletion request. Editing and new reports are paused. An administrator will review the request. ${state.profile.owner_id===state.session.user.id?'<button class="text-btn" data-action="cancel-deletion">Cancel request</button>':''}</p></div>`;}
function renderMessage(m){const asst=m.role==='assistant',e=m.evidence||{};return `<article class="message ${asst?'assistant':'user'}"><span class="avatar">${asst?icon('spark'):'You'}</span><div class="message-text"><div class="message-label">${asst?(m.intro?'PATHFINDER · GETTING STARTED':'PATHFINDER · AI INTERVIEW'):'YOU'}</div><div class="message-body">${esc(m.content)}</div>${asst&&e.changes?.length?`<div class="proposed-change"><strong>Suggested profile updates</strong><dl>${e.changes.map(c=>`<div><dt>${esc(c.field)}:</dt><dd>${esc(c.value)}</dd></div>`).join('')}</dl><p class="tiny">Review these homeowner-provided facts before saving them.</p>${button('review-changes','Review & apply','outline','check',`data-message="${m.id}"`)}</div>`:''}${asst&&e.citations?.length?`<div class="message-sources">${e.retrievalMode==='vector'?'Semantic':'Keyword'} retrieval · source evidence${e.citations.map(c=>`<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.title)} · ${date(c.checked_at)} ${icon('external')}</a>`).join('')}</div>`:''}</div></article>`;}
function interviewView(){if(!state.profile)return emptyHome();const p=state.profile.data,plan=state.profile.plan,ai=state.session.aiConfigured;return `${pageHead('LET’S GET TO KNOW YOUR HOME','A conversation. A clearer picture.','Share what you know. We’ll help uncover what needs a closer look.')}${state.profile.deletion_requested_at?deletionNotice():''}${!ai?`<div class="notice">${icon('info')}<p>The live AI interview is awaiting the OpenAI API key. You can already complete the structured home profile and explore your pathway. <button class="text-btn" data-action="edit-home">Update home details</button></p></div>`:''}<div class="chat-layout"><section class="chat-panel"><div class="chat-head"><div class="home-square">${icon('spark')}</div><div><strong>Your home energy guide</strong><small>${ai?'OpenAI-powered interview · grounded in saved SEAI evidence':'AI not connected · your home profile is saved'}</small></div></div><div class="chat-messages" id="chat-messages">${renderMessage({role:'assistant',intro:true,content:`Hello! Let’s make a practical plan for your ${type(p.type).toLowerCase()} in ${p.county}.\n\n${plan.questions[0]?.title||'What matters most to you: comfort, lower energy use, or moving away from fossil-fuel heating?'}\n\nIt’s fine if you’re not sure. We’ll record the uncertainty and turn it into a useful question for your assessor.`})}${state.messages.map(renderMessage).join('')}${state.busy?'<div class="message-label">Checking the source evidence and your home profile…</div>':''}</div><form class="chat-input" id="chat-form"><textarea name="message" maxlength="2500" placeholder="Tell me about your home, or ask about an upgrade…" aria-label="Your message" required ${!ai||!p.consent||state.busy?'disabled':''}>${esc(state.drafts[state.profile.id]||'')}</textarea><div class="chat-input-footer"><small>No exact addresses, MPRNs or sensitive personal details.</small><button class="primary-btn" type="submit" ${!ai||!p.consent||state.busy?'disabled':''}>${icon('arrow')} Send</button></div></form></section><aside class="chat-aside"><div class="card"><div class="eyebrow">YOUR HOME, YOUR INFORMATION</div><h3>Start with what you know.</h3><p>You can edit your details at any time. Suggested changes from the interview always need your confirmation.</p><div class="checklist-item">${icon('home')} ${type(p.type)} · ${p.area} m² · ${p.year}</div><div class="checklist-item">${icon('bolt')} ${esc(p.heating)} heating · BER ${esc(p.ber)}</div><div class="checklist-item">${icon('layers')} ${esc(p.walls)} walls · ${esc(p.attic)} attic insulation</div><div class="mt20">${button('edit-home','Update home details','outline','edit')}</div></div><div class="card"><h3>${icon('shield')} AI processing permission</h3><p class="tiny">When enabled, your building details and interview messages are sent to OpenAI to prepare replies. Avoid personal identifiers. Public SEAI text is embedded separately; homeowner profiles are not added to the public source index.</p><label class="checkbox-row"><input type="checkbox" id="ai-consent" ${p.consent?'checked':''} ${state.profile.owner_id!==state.session.user.id?'disabled':''}/> <span>I agree to AI processing for this home. I can turn it off at any time.</span></label><a href="#privacy" class="tiny">Read about storage and retention ${icon('arrow')}</a></div></aside></div>${berPotentialCard(plan)}${berPanel(plan)}${footnote()}`;}
function reports(){return `${pageHead('YOUR DOCUMENT LIBRARY','Good plans are worth keeping.','Every saved brief is a versioned snapshot. Revisit it whenever you need.',state.profile?button('generate-report','Create a contractor brief','primary','plus'):'')}${state.profile?`<div class="flex split report-home-select"><p class="tiny mb0">New briefs will use <strong>${esc(state.profile.data.name)}</strong> and its selected pathway.</p>${selector()}</div>`:''}${state.reports.length?`<div class="report-grid">${state.reports.map(r=>`<article class="report-card"><div class="report-cover">${icon('file')}<strong>Your home.<br>A clear way forward.</strong><small>CONTRACTOR ASSESSMENT PACK</small></div><div class="report-info"><h3>${esc(r.home)}</h3><p>Version ${r.version} · ${date(r.created_at)} · PDF</p><div class="actions"><span class="pill">Saved snapshot</span><a class="text-btn" href="/api/reports/${r.id}/pdf" target="_blank" rel="noopener">View brief ${icon('external')}</a></div></div></article>`).join('')}</div>`:`<div class="empty card">${icon('file')}<h2>Your next conversation, prepared.</h2><p>Create your first contractor brief. It will include your profile, ordered measures, costs, questions and dated SEAI sources.</p>${state.profile?button('generate-report','Save your first brief','primary','file'):button('new-home','Add your home','primary','plus')}</div>`}${footnote()}`;}
function sources(){const data=state.sources;if(!data)return '';const active=data.sources.filter(s=>s.active===1);return `${pageHead('EVIDENCE YOU CAN FOLLOW','Clear advice starts with clear sources.','Official SEAI pages, saved with retrieval dates and content fingerprints.',state.session.user.role==='admin'?button('refresh-sources','Refresh SEAI sources','outline','refresh'):'<span class="pill">OFFICIAL SOURCE LIBRARY</span>')}${data.lastRefresh?.results.some(r=>r.status==='failed')?`<div class="notice">${icon('info')}<p>Last automatic refresh: ${date(data.lastRefresh.at)}. One or more SEAI requests failed (${esc([...new Set(data.lastRefresh.results.filter(r=>r.status==='failed').map(r=>r.code||'retrieval unavailable'))].join(', '))}). Previous dated evidence is retained; do not treat it as newly fetched.</p></div>`:''}${data.berReviewRequired?'<div class="notice"><p>BER sources changed. Potential ratings are withheld until an administrator reviews the BER thresholds, methodology and model assumptions.</p></div>':''}${data.reviewRequired?`<div class="notice">${icon('info')}<p>Source content has changed since the catalogue review. Numeric grant estimates are withheld until an administrator checks the values and conditions against the updated pages.</p></div>`:''}<div class="stats"><div class="stat"><div class="stat-label">Official source pages</div><div class="stat-value">${active.length} SEAI sources</div><small>Allowlisted grant pages · Ireland only</small></div><div class="stat"><div class="stat-label">Semantic index</div><div class="stat-value">${active.reduce((n,s)=>n+Number(s.embedded_chunks),0)} vector chunks</div><small>${active.some(s=>Number(s.embedded_chunks)>0)?'OpenAI embeddings · timestamped source versions':'Awaiting embeddings · keyword retrieval available'}</small></div><div class="stat"><div class="stat-label">Grant catalogue review</div><div class="stat-value green">${date(data.reviewedAt)}</div><small>${data.reviewRequired?'Changed content requires review':'Manually checked values · recheck before applying'}</small></div></div><div class="card"><h2>Find the evidence behind an upgrade</h2><form class="source-search" id="source-search"><input class="field" name="query" placeholder="Try “heat pump eligibility” or “attic insulation”" aria-label="Search SEAI evidence" minlength="2" maxlength="500" required/><button class="primary-btn" type="submit">${icon('search')} Search sources</button></form><div id="search-results" aria-live="polite"></div></div><div class="pathway-list">${active.map(s=>`<article class="source-card"><div class="source-icon">${icon('book')}</div><div class="source-content"><h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${icon('external')}</a></h3><p>SEAI · ${s.kind==='scraped'?'Retrieved webpage snapshot':'Manually verified source summary; full scrape pending'}</p><div class="source-meta"><span>Retrieved ${date(s.retrieved_at)}</span><span>Checked ${date(s.checked_at)}</span><span>${s.chunks} chunks · ${s.embedded_chunks} embedded</span></div><details class="step-details"><summary>Source fingerprint</summary><p class="prewrap tiny">SHA-256: ${s.digest}<br>Snapshot: ${s.id}</p></details></div><span class="pill">${s.kind==='scraped'?'Saved webpage':'Reviewed summary'}</span></article>`).join('')}</div><div class="two-col mt20"><div class="card"><h3>Public evidence. Private home profiles.</h3><p>Only public SEAI content enters the source index. Your home details, conversations and PDFs are stored separately and protected by account permissions.</p></div><div class="card"><h3>Grants can change. History stays.</h3><p>Refreshing creates a new source version when content changes. Earlier report snapshots keep the source IDs and dates used when they were generated.</p></div></div>${data.sources.some(s=>s.active!==1)?`<details class="card"><summary>Previous source versions (${data.sources.filter(s=>s.active!==1).length})</summary>${data.sources.filter(s=>s.active!==1).map(s=>`<p class="tiny mt20">${esc(s.title)} · ${date(s.retrieved_at)} · ${s.kind} · ${s.digest.slice(0,16)}…</p>`).join('')}</details>`:''}${footnote()}`;}
function privacy(){return `${pageHead('PRIVACY & CONTROL','Your home. Your information.','Understand what is saved, who can see it, and how long it stays.')}<div class="two-col"><div class="card"><div class="home-square">${icon('shield')}</div><h2 class="mt20">A private workspace</h2><p>Homeowners can access their own profiles, interviews and reports. Advisers can access only homes assigned to them. Workspace administrators manage access, retention, source review and deletion requests.</p><p>Viewing profiles and PDFs, changing details, generating reports and administrative actions are recorded in an audit trail. The trail contains event metadata, not interview content.</p><p class="tiny">This is an MVP governance implementation, not a certification of regulatory compliance.</p></div><div class="card"><div class="home-square">${icon('clock')}</div><h2 class="mt20">Kept for a defined purpose</h2><p>Profiles inactive for <strong>${state.session.retentionDays} days</strong> are eligible for permanent deletion by the retention job. Related conversations and PDFs are deleted with the profile.</p><p>Audit events have a separate <strong>${state.session.auditRetentionDays}-day</strong> retention period. Viewing a profile does not reset its retention clock; editing, interviewing or generating a report does.</p><p class="tiny">Account credentials remain until an operator removes the account. Database backups follow the deployment’s separate lifecycle; deletion is not instantaneous in backups.</p></div></div>${state.profile?`<div class="card"><h2>${esc(state.profile.data.name)} · your controls</h2><div class="settings-row"><div><strong>AI interview processing</strong><p>Send your building details and interview text to OpenAI for replies. Turning this off stops new AI requests; it does not delete past messages. API requests use store:false; provider retention is governed by your organisation’s OpenAI agreement.</p></div><input type="checkbox" id="ai-consent" aria-label="Allow AI processing" ${state.profile.data.consent?'checked':''} ${state.profile.owner_id!==state.session.user.id?'disabled':''}/></div><div class="settings-row"><div><strong>${state.profile.deletion_requested_at?'Deletion requested':'Request deletion of this home'}</strong><p>Ask the administrator to permanently delete this profile, its interview history and all generated PDFs. Minimal audit records remain for the configured audit period.</p></div>${state.profile.owner_id===state.session.user.id?button(state.profile.deletion_requested_at?'cancel-deletion':'request-deletion',state.profile.deletion_requested_at?'Cancel request':'Request deletion',state.profile.deletion_requested_at?'outline':'danger','trash'):''}</div></div>`:''}<div class="notice info">${icon('lock')}<p>Do not add your exact address, MPRN, account numbers or sensitive personal details to an interview. Keep these for the qualified professional and the official grant application.</p></div>${footnote()}`;}
function governance(){const a=state.admin;if(!a)return '';return `${pageHead('WORKSPACE ADMINISTRATION','Good governance, built into the journey.','Manage invitations, adviser access, evidence and the lifecycle of homeowner records.','<span class="pill">ADMINISTRATOR</span>')}<div class="admin-grid"><section><div class="card"><h2>Invite someone to the workspace</h2><p>Invitation-only access. Links are single-use and expire after 72 hours. Share the generated link securely yourself.</p><form id="invite-form" class="inline-form"><label class="form-field"><span>Email address</span><input name="email" type="email" required maxlength="180" placeholder="name@example.ie"/></label><label class="form-field"><span>Role</span><select name="role"><option value="homeowner">Homeowner</option><option value="adviser">Adviser</option><option value="admin">Administrator</option></select></label><button class="primary-btn" type="submit">${icon('plus')} Create invite</button></form><div id="invite-result" class="mt20"></div></div><div class="card"><h2>Retention policy</h2><p>Configure inactivity retention for profiles and a separate period for audit records. A retention run permanently removes expired profiles and their associated reports and conversations.</p><form id="retention-form"><div class="form-grid"><label class="form-field"><span>Profile inactivity · days</span><input name="retentionDays" type="number" min="30" max="3650" required value="${a.settings.retention_days}"/></label><label class="form-field"><span>Audit events · days</span><input name="auditRetentionDays" type="number" min="30" max="3650" required value="${a.settings.audit_retention_days}"/></label></div><div class="flex mt20"><button class="primary-btn" type="submit">Save policy</button>${button('run-retention','Run retention now','outline','clock')}</div></form><p class="tiny mt20 mb0">${a.settings.last_retention_run?`Last run: ${date(JSON.parse(a.settings.last_retention_run).at)}. ${JSON.parse(a.settings.last_retention_run).purged} profiles purged.`:'No retention job has run yet. Configure the daily Cloud Run job before onboarding real households.'}</p></div><div class="card"><h2>Adviser assignments</h2><p>Assign a home to one adviser, or remove access. Share only with the homeowner’s agreement.</p><form id="assignment-form" class="inline-form"><label class="form-field"><span>Home</span><select name="profileId" required>${state.profiles.map(p=>`<option value="${p.id}">${esc(p.data.name)}</option>`).join('')}</select></label><label class="form-field"><span>Adviser</span><select name="adviserId"><option value="">No adviser · remove access</option>${a.users.filter(u=>u.role==='adviser').map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><button class="primary-btn" type="submit" ${!state.profiles.length?'disabled':''}>Save access</button></form><div class="mt20">${state.profiles.map(p=>`<p class="tiny">${esc(p.data.name)} → ${esc(a.users.find(u=>u.id===p.adviser_id)?.name||'No adviser assigned')}</p>`).join('')}</div></div><div class="card"><h2>Deletion requests</h2>${a.deletions.length?a.deletions.map(d=>`<div class="settings-row"><div><strong>${esc(state.profiles.find(p=>p.id===d.id)?.data.name||d.id)}</strong><p>Requested ${date(d.deletion_requested_at)}. Includes all conversations and PDFs.</p></div>${button('purge-profile','Review deletion','danger','trash',`data-id="${d.id}"`)}</div>`).join(''):'<p class="mb0">No pending homeowner deletion requests.</p>'}</div></section><aside><div class="card"><h2>SEAI evidence pipeline</h2><p>Fetch four allowlisted SEAI grant pages, preserve source versions and embed the public text. A changed page pauses numeric support estimates until review.</p><div class="flex wrap">${button('refresh-sources','Refresh & index','primary','refresh')}${button('index-sources','Index saved evidence','outline','book')}${button('review-grants','Review catalogue','outline','check')}</div><div id="refresh-result" class="mt20"></div><p class="tiny mt20 mb0">${state.session.aiConfigured?'OpenAI key is configured.':'OpenAI key is missing. Scraping can run; embedding will wait.'} ${state.session.storage}.</p></div><div class="card"><h2>Workspace members <span class="muted">${a.users.length}</span></h2>${a.users.map(u=>`<div class="settings-row"><div><strong>${esc(u.name)}</strong><p>${esc(u.email)}</p></div><span class="pill">${u.role}</span></div>`).join('')}</div><div class="card"><div class="section-heading"><h2>Audit trail</h2><span class="pill">Latest 150 events</span></div><div class="audit-list">${a.audit.map(e=>`<div class="audit-row">${icon('shield')}<div><strong>${esc(e.action)}</strong><small>${new Date(e.created_at).toLocaleString('en-IE')} · ${esc(e.actor_id.slice(0,14))}</small><details><summary class="tiny muted">Event metadata</summary><p class="tiny prewrap">${esc(e.detail)}<br>Target: ${esc(e.target_id)}</p></details></div></div>`).join('')||'<p class="tiny">No events recorded yet.</p>'}</div></div></aside></div>${footnote()}`;}
function login(){const invite=location.hash.startsWith('#invite=')?location.hash.slice(8):'';return `<main class="login-shell"><section class="login-story">${logo()}<div class="eyebrow">FOR THE HOME YOU HAVE. THE FUTURE YOU WANT.</div><h1>A warmer home.<br>A clearer way forward.</h1><p>Your personal guide to home energy upgrades in Ireland. The right steps, the evidence behind them, and a plan you can come back to.</p><img class="house" src="/house.svg" alt="An energy-efficient Irish home"/></section><section class="login-form"><div><span class="pill">${icon('lock')}INVITATION-ONLY WORKSPACE</span><h2 class="mt20">${invite?'Make yourself at home.':'Welcome home.'}</h2><p>${invite?'Create your account to accept your invitation.':'Sign in to continue your home’s energy journey.'}</p><form id="${invite?'register':'login'}-form">${invite?'<label class="form-field"><span>Your name</span><input name="name" autocomplete="name" required maxlength="80"/></label>':'<label class="form-field"><span>Email address</span><input name="email" type="email" autocomplete="username" required/></label>'}<label class="form-field"><span>Password${invite?' · at least 12 characters':''}</span><input name="password" type="password" autocomplete="${invite?'new-password':'current-password'}" ${invite?'minlength="12"':''} maxlength="200" required/></label><div class="form-error" id="auth-error" role="alert"></div><button class="primary-btn full" type="submit">${invite?'Accept invitation':'Sign in'}${icon('arrow')}</button></form>${state.session.demo&&!invite?`<div class="login-divider">EXPLORE THE LOCAL PREVIEW</div>${button('demo-homeowner','Explore two example homes','outline','home','data-role="homeowner"')}<p class="tiny mt20">Synthetic homes only. Preview access is disabled in production.</p>`:''}<p class="tagline">Need an invitation or a password reset? Contact your workspace administrator.</p></div></section></main>`;}
function render(){if(!location.hash||location.hash==='#home'){$('#app').innerHTML=landing(state.session);return;}if(!state.session?.user){$('#app').innerHTML=login();return;}const u=state.session.user,nav=[['overview','home','Overview'],['interview','chat','Home interview'],['pathway','route','Your pathway'],['compare','compare','Compare scenarios'],['funding','euro','Grants & what you pay'],['reports','file','Saved reports']],pages={funding:()=>state.profile?`${pageHead('GRANTS & COSTS','Know what you could pay.','Compare funding routes and see the evidence behind every estimate.')}${finance(state.profile.plan)}`:emptyHome(),overview,pathway,compare,interview:interviewView,reports,sources,privacy,governance};const titles={funding:'Grants & what you pay',overview:'Overview',interview:'Home interview',pathway:'Your pathway',compare:'Compare scenarios',reports:'Saved reports',sources:'SEAI evidence',privacy:'Privacy & data',governance:'Governance'};$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar">${logo()}<div class="nav-label">YOUR HOME JOURNEY</div><nav aria-label="Main navigation">${nav.map(([page,ico,label])=>`<button class="nav-item ${state.page===page?'active':''}" data-action="navigate-${page}" ${state.page===page?'aria-current="page"':''}>${icon(ico)}${label}${page==='reports'&&state.reports.length?`<span class="count">${state.reports.length}</span>`:''}</button>`).join('')}<div class="nav-label mt20">KNOWLEDGE & SUPPORT</div>${[['sources','book','SEAI evidence'],['privacy','shield','Privacy & data'],...(u.role==='admin'?[['governance','settings','Governance']]:[])].map(([page,ico,label])=>`<button class="nav-item ${state.page===page?'active':''}" data-action="navigate-${page}">${icon(ico)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('leaf')}<strong>A little progress goes a long way.</strong><p>A good retrofit starts with understanding your home.</p></div>${state.session.demo?`<button class="nav-item" data-action="demo-${u.role==='admin'?'homeowner':'admin'}">${icon('users')} Preview ${u.role==='admin'?'homeowner':'governance'}</button>`:''}<div class="user-chip"><span class="avatar">${esc(u.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div><strong>${esc(u.name)}</strong><small>${u.role} workspace</small></div><button data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main><header class="topbar"><div class="flex"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="crumb"><span>Your home journey</span>${icon('chevron')}<strong>${titles[state.page]||'Overview'}</strong></div></div><div class="top-actions"><span class="connection"><span class="dot"></span>${state.session.demo?'Local preview':'Private workspace'} · ${state.session.aiConfigured?'AI configured':'AI setup pending'}</span>${u.role==='homeowner'?button('new-home','Add a home','outline','plus'):u.role==='admin'?button('navigate-governance','Workspace','outline','settings'):''}</div></header><div class="content" id="page-content">${journey(state.profile,state.page)}${(pages[state.page]||overview)()}</div></main></div>`;const chat=$('#chat-messages');if(chat)chat.scrollTop=chat.scrollHeight;}
function closeModal(){const el=$('#modal-root');el.innerHTML='';document.body.classList.remove('modal-open');lastFocus?.focus();}
function modal(title,sub,body,footer='',small=false){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${sub}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}${footer}</section></div>`;document.body.classList.add('modal-open');$('.modal input,.modal button,.modal select')?.focus();}
const options=(values,current)=>values.map(v=>{const [key,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(key)}" ${key===current?'selected':''}>${esc(label)}</option>`;}).join('');
function groupHomeSections(){const body=document.querySelector('#home-form .modal-body');if(!body)return;const headings=[...body.querySelectorAll(':scope > .form-section')];for(const [i,h] of headings.entries()){const section=document.createElement('details');section.className='home-section';section.open=i<2;const summary=document.createElement('summary');summary.textContent=h.textContent;h.before(section);section.append(summary);let n=h.nextSibling;while(n&&!(n.nodeType===1&&(n.classList.contains('form-section')||n.classList.contains('form-error')))){const next=n.nextSibling;section.append(n);n=next;}h.remove();}}
document.addEventListener('invalid',event=>{const section=event.target.closest('details');if(section)section.open=true;},true);
function homeForm(isNew=false,patch={}){const p={applicantType:'unknown',ahbRegistered:'unknown',ownerOccupier:'unknown',qualifyingPayment:'unknown',paymentConditions:'unknown',managementConsent:'unknown',roofAccess:'unknown',roofHeatLoss:'unknown',berRecordId:'',name:'My home',county:'Dublin',type:'semi',year:1980,occupiedYear:1980,area:100,ber:'unknown',heating:'gas',walls:'unknown',attic:'unknown',damp:'unknown',ventilation:'unknown',budget:40000,goal:'balanced',priorGrants:'unknown',ownership:'owner',mprn:'unknown',traditional:'unknown',consent:false,evidence:[],synthetic:false,...(!isNew?state.profile.data:{}),...patch};const field=(label,key,type='text',extra='')=>`<label class="form-field"><span>${label}</span><input name="${key}" type="${type}" value="${esc(p[key])}" required ${extra}/></label>`;const select=(label,key,values)=>`<label class="form-field"><span>${label}</span><select name="${key}">${options(values,p[key])}</select></label>`;modal(isNew?'Let’s get to know your home.':'Your home, in a little more detail.',isNew?'Use approximate details if needed. Choose “Not sure” rather than guessing.':'Your pathway updates when you save. Changing BER-derived dwelling facts removes the linked example record. This does not verify technical suitability.',`<form id="home-form" data-new="${isNew}" data-ber="${esc(p.berRecordId||'')}"><div class="modal-body"><div class="form-section">The basics</div><div class="form-grid">${field('A name for this home','name','text','maxlength="80"')}${select('County','county',['Carlow','Cavan','Clare','Cork','Donegal','Dublin','Galway','Kerry','Kildare','Kilkenny','Laois','Leitrim','Limerick','Longford','Louth','Mayo','Meath','Monaghan','Offaly','Roscommon','Sligo','Tipperary','Waterford','Westmeath','Wexford','Wicklow'])}${select('Dwelling type','type',[['semi','Semi-detached / end-terrace'],['detached','Detached house'],['terrace','Mid-terrace'],['apartment','Apartment']])}${field('Year built','year','number','min="1700" max="2026"')}${field('Year first occupied','occupiedYear','number','min="1700" max="2026"')}${field('Floor area · m²','area','number','min="25" max="600"')}${select('BER exactly as printed — old and new scales accepted','ber',[['unknown','Not sure / no certificate'],'A0','A','B','C','D','E','F','G','A1','A2','A3','B1','B2','B3','C1','C2','C3','D1','D2','E1','E2'])}${select('Current heating','heating',[['gas','Gas boiler'],['oil','Oil boiler'],['solid','Solid fuel'],['storage','Electric storage'],['heatpump','Heat pump'],['other','Other']])}</div><div class="form-section">Fabric & healthy air</div><div class="form-grid">${select('Wall construction','walls',[['unknown','Not sure'],['cavity','Cavity walls'],['solid','Solid walls']])}${select('Attic insulation','attic',[['unknown','Not sure'],['none','None'],['partial','Some / needs improvement'],['good','Already well insulated']])}${select('Damp or condensation','damp',[['unknown','Not sure'],['yes','Yes'],['no','No known issues']])}${select('Ventilation assessment','ventilation',[['unknown','Not assessed / not sure'],['assessed','Assessed by a professional']])}${select('Traditional construction','traditional',[['unknown','Not sure'],['yes','Yes, traditional building'],['no','No']])}</div><div class="form-section">Your priorities & grant eligibility</div><div class="form-grid">${field('Planning budget · €','budget','number','min="0" max="500000" step="500"')}${select('Your preferred approach','goal',Object.entries(scenarioNames))}${select('Who is applying for the grant?','applicantType',[['unknown','Not sure / choose applicant type'],['private','Private homeowner or landlord'],['ahb','Representative of an Approved Housing Body'],['tenant','Tenant — property owner must apply']])}${select('AHB: valid AHBRA registration?','ahbRegistered',[['unknown','Not sure / not applicable'],['yes','Yes'],['no','No']])}${select('Relationship to the home','ownership',[['owner','I / the represented organisation own the home'],['other','Other / owner consent needed']])}${select('Does the home have an MPRN?','mprn',[['unknown','Not sure'],['yes','Yes — do not enter the number'],['no','No']])}${select('Previous SEAI grants for this home','priorGrants',[['unknown','Not sure'],['none','None'],['yes','Yes — individual review needed']])}</div><div class="form-section">Funding eligibility & apartment permissions</div><p class="tiny">Optional eligibility screening, stored with this home under its retention policy. Payment selections are excluded from the AI profile and contractor PDF; the PDF contains only the screening outcome. Do not provide PPSNs, medical details or payment documents.</p><div class="form-grid">${select('Do you live in the home?','ownerOccupier',[['unknown','Not sure / prefer not to say'],['yes','Yes'],['no','No']])}${select('Qualifying payment','qualifyingPayment',[['unknown','Not sure / prefer not to say'],['none','None of these'],['fuel','Fuel Allowance'],['jobseeker','Jobseeker’s Allowance'],['working-family','Working Family Payment'],['one-parent','One-Parent Family Payment'],['domiciliary','Domiciliary Care Allowance'],['carer','Carer’s Allowance'],['disability','Disability Allowance']])}${select('Additional payment conditions met?','paymentConditions',[['unknown','Not sure / not applicable'],['yes','Yes'],['no','No']])}${select('Apartment: management consent obtained?','managementConsent',[['unknown','Not sure / not applicable'],['yes','Yes'],['no','No']])}${select('Apartment: top-floor or roof directly loses heat outdoors?','roofHeatLoss',[['unknown','Not sure / not applicable'],['yes','Yes, exposed roof above this apartment'],['no','No, another apartment is above']])}${select('Apartment: suitable roof/attic access?','roofAccess',[['unknown','Not sure / not applicable'],['yes','Yes'],['no','No']])}</div><p class="tiny">Jobseeker’s/Disability: payment over six months AND child under seven. Carer’s: live with the person cared for. SEAI verifies eligibility. For apartments, confirm shared-building permissions even if roof access is available.</p><div class="form-section">Evidence you have available</div><p class="tiny">Record availability only. Use the BER evidence form for certificate extraction; other documents are recorded as available only.</p><div class="form-grid">${[['ber','BER certificate'],['heat-loss','Heat-loss assessment'],['ventilation','Ventilation assessment'],['roof','Roof inspection'],['wall-survey','Wall construction survey']].map(([k,l])=>`<label class="checkbox-row"><input type="checkbox" name="evidence" value="${k}" ${p.evidence.includes(k)?'checked':''}/>${l}</label>`).join('')}</div><div class="notice info mt20">${icon('info')}<p>AI permission is managed separately in the interview or privacy page. Personal identifiers are not needed to plan your upgrades.</p></div><div class="form-error" id="home-error" role="alert"></div></div><div class="modal-footer"><button type="button" class="outline-btn" data-action="close-modal">Cancel</button><button type="submit" class="primary-btn">${icon('check')}${isNew?'Create home profile':'Save & update pathway'}</button></div></form>`);groupHomeSections();}
function confirmModal(title,body,action,extra='',label='Confirm'){modal(title,'Please review before continuing.',`<div class="modal-body"><p>${body}</p></div>`,`<div class="modal-footer">${button('close-modal','Cancel','outline','')}${button(action,label,'primary','check',extra)}</div>`,true);}
function showBerBaseline(extracted=null){modal('Your current BER evidence','Review the certificate fields before any estimate is made.',berBaselineForm(state.profile.data,extracted));}
async function saveBerBaseline(baseline){const updated=await api(`/profiles/${state.profile.id}/ber-baseline`,'POST',{revision:state.profile.revision,baseline});state.profile=updated;state.profiles=state.profiles.map(p=>p.id===updated.id?updated:p);return updated;}
async function saveProfile(data){const updated=await api(`/profiles/${state.profile.id}`,'PUT',{revision:state.profile.revision,data});state.profile=updated;state.profiles=state.profiles.map(p=>p.id===updated.id?updated:p);return updated;}
async function generateReport(){if(!state.profile)return toast('Add a home profile first.');toast('Preparing and saving your contractor brief…');const r=await api(`/profiles/${state.profile.id}/reports`,'POST',{scenario:state.profile.data.goal});state.reports=(await api('/reports')).reports;toast(`Version ${r.version} saved. You can reopen it from your report library.`);go('reports');}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(b.disabled)return;try{if(a.startsWith('navigate-')){go(a.slice(9));return;}if(a==='menu'){$('#sidebar').classList.toggle('open');return;}if(a==='close-modal'){closeModal();return;}if(a==='edit-home'){homeForm();return;}if(a==='edit-ber-baseline'){showBerBaseline();return;}if(a==='clear-ber-baseline'){await saveBerBaseline(null);closeModal();render();toast('Baseline removed; the reported rating is retained.');return;}if(a==='new-home'){homeForm(true);return;}if(a==='question'){homeForm();return;}if(a==='logout'){await api('/logout','POST',{});sessionStorage.setItem('rf-signed-out','true');state.session.user=null;render();return;}if(a.startsWith('demo-')){const role=a.slice(5);state.session.user=(await api('/demo-session','POST',{role})).user;sessionStorage.removeItem('rf-signed-out');await loadProfiles();if(role==='admin'){await loadPage('governance');location.hash='governance';}else{await loadPage('overview');location.hash='overview';}return;}if(a==='select-scenario'){b.disabled=true;if(b.dataset.scenario!==state.profile.data.goal)await saveProfile({...state.profile.data,goal:b.dataset.scenario});go('pathway');return;}if(a==='generate-report'){b.disabled=true;await generateReport();return;}if(a==='review-changes'){const m=state.messages.find(m=>m.id===b.dataset.message);if(!m)return;homeForm(false,Object.fromEntries(m.evidence.changes.map(c=>[c.field,c.value])));return;}if(a==='request-deletion'){confirmModal('Request deletion of this home?',`The administrator will be asked to remove <strong>${esc(state.profile.data.name)}</strong>, all its interviews and every PDF report. You can cancel the request until it is processed.`,'confirm-deletion');return;}if(a==='confirm-deletion'||a==='cancel-deletion'){await api(`/profiles/${state.profile.id}/deletion`,'POST',{cancel:a==='cancel-deletion'});closeModal();await loadProfiles();render();toast(a==='cancel-deletion'?'Deletion request cancelled.':'Deletion request submitted to the administrator.');return;}if(a==='run-retention'){confirmModal('Run the retention policy now?','Expired inactive home profiles and all related interviews and PDFs will be permanently removed. This cannot be undone.','confirm-retention','','Run retention');return;}if(a==='confirm-retention'){b.disabled=true;const r=await api('/admin/retention','POST',{});closeModal();await loadProfiles();await loadPage('governance');toast(`${r.purged} expired profiles removed.`);return;}if(a==='purge-profile'){confirmModal('Permanently delete this home?',`This fulfils the homeowner’s deletion request. It removes the home profile, interview history and all saved PDFs. Minimal audit metadata remains. This cannot be undone.`,'confirm-purge',`data-id="${b.dataset.id}"`,'Permanently delete');return;}if(a==='confirm-purge'){b.disabled=true;await api(`/admin/profiles/${b.dataset.id}`,'DELETE',{});closeModal();await loadProfiles();await loadPage('governance');toast('Profile, conversations and PDFs permanently deleted.');return;}if(a==='refresh-sources'){b.disabled=true;b.textContent='Fetching & indexing…';toast('Retrieving official SEAI pages. This can take a few minutes.');const r=await api('/admin/sources/refresh','POST',{});await loadProfiles();if(state.page==='sources')await loadPage('sources');else await loadPage('governance');const target=$('#refresh-result');if(target)target.innerHTML=r.results.map(x=>`<p class="tiny"><strong>${esc(x.title)}</strong>: ${esc(x.status)} · ${x.indexed||0} chunks embedded${x.indexError?` · ${esc(x.indexError)}`:''}${x.error?` · ${esc(x.error)}`:''}</p>`).join('');toast(r.results.some(r=>r.status==='failed')?'Some pages could not be refreshed. Previous evidence is retained.':'Sources saved. Review changed grant content before restoring numeric estimates.');return;}if(a==='index-sources'){b.disabled=true;toast('Embedding the existing public evidence…');const r=await api('/admin/sources/index','POST',{});toast(`${r.indexed} source chunks embedded. Original retrieval dates are unchanged.`);await loadPage('governance');return;}if(a==='review-grants'){modal('Review the grant catalogue','Check each value and eligibility condition against the latest official pages.',`<div class="modal-body"><p class="tiny">The fixed catalogue was reviewed on 9 September 2026. If a value or condition has changed, update server/catalog.js and server/pathway.js, test the change, and redeploy before marking this reviewed.</p><table class="compare-table grant-table"><thead><tr><th>Measure</th><th>Detached</th><th>Semi/end-terrace</th><th>Mid-terrace</th></tr></thead><tbody><tr><td>Attic</td><td>€2,000</td><td>€1,500</td><td>€1,400</td></tr><tr><td>Cavity</td><td>€1,800</td><td>€1,300</td><td>€850</td></tr><tr><td>External wall*</td><td>€8,000</td><td>€6,000</td><td>€3,500</td></tr><tr><td>Heat pump bundle*</td><td colspan="3">Up to €12,500, only for eligible components</td></tr><tr><td>Solar 4 kWp*</td><td colspan="3">Up to €1,800</td></tr></tbody></table><p class="tiny mt20">*Subject to all relevant scheme conditions. Traditional-building wall support is withheld; higher welfare/first-time-buyer rates and supplementary wall grants are not automatically modelled.</p><a href="#sources" data-action="review-open-sources" class="tiny">Open the source library before confirming</a><label class="checkbox-row"><input type="checkbox" id="review-confirm"/><span>I have checked all values and modelled eligibility conditions against every active source snapshot.</span></label></div>`,`<div class="modal-footer">${button('close-modal','Cancel','outline','')}${button('confirm-review','Mark reviewed','primary','check')}</div>`);return;}if(a==='review-open-sources'){closeModal();go('sources');return;}if(a==='confirm-review'){if(!$('#review-confirm').checked)return toast('Check the catalogue against the source pages first.');await api('/admin/sources/review','POST',{confirm:true});closeModal();await loadProfiles();await loadPage(state.page);toast('Catalogue review recorded in the audit trail.');return;}}catch(e){toast(e.message);}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('change',async event=>{try{if(['home-select','ribbon-home-select'].includes(event.target.id)){state.profile=state.profiles.find(p=>p.id===event.target.value);localStorage.setItem('rf-home',state.profile.id);await loadPage(state.page);}if(event.target.id==='ai-consent'){const value=event.target.checked;await saveProfile({...state.profile.data,consent:value});render();toast(value?'AI processing enabled for this home.':'AI processing turned off. Existing records are retained.');}}catch(e){event.target.checked=!event.target.checked;toast(e.message);}});
document.addEventListener('submit',async event=>{const f=event.target;event.preventDefault();const submit=f.querySelector('button[type="submit"]'),form=new FormData(f);if(submit)submit.disabled=true;try{if(f.id==='login-form'||f.id==='register-form'){const data=Object.fromEntries(form);if(f.id==='register-form')data.token=location.hash.slice(8);const result=await api(f.id==='login-form'?'/login':'/register','POST',data);state.session.user=result.user;sessionStorage.removeItem('rf-signed-out');await loadProfiles();location.hash='interview';await loadPage('interview');}if(f.id==='ber-certificate-form'){
 const file=form.get('certificate');if(!file||file.size>5*1024*1024)throw Error('Choose a PDF no larger than 5 MB.');
 const response=await fetch('/api/profiles/'+state.profile.id+'/ber-certificate',{method:'POST',headers:{'Content-Type':'application/pdf'},body:file});const result=await response.json();if(!response.ok)throw Error(result.error||'Could not read this certificate.');showBerBaseline(result);
 }if(f.id==='ber-baseline-form'){
 const baseline={source:form.get('source'),rating:form.get('rating'),issuedOn:form.get('issuedOn'),primaryEnergy:form.get('primaryEnergy')===''?null:Number(form.get('primaryEnergy')),confirmed:form.has('confirmed'),unchanged:form.has('unchanged')};
 await saveBerBaseline(baseline);closeModal();render();toast('BER evidence saved. Each scenario now explains its potential or missing evidence.');
 }if(f.id==='ber-form'){

 const {record:b}=await api('/profiles/'+state.profile.id+'/ber-check','POST',{sampleMprn:form.get('sampleMprn')});
 modal('Synthetic BER result',b.notice,'<div class="modal-body"><h3>'+esc(b.id)+' · BER '+esc(b.rating)+'</h3><p>'+b.area+' m² · Built '+b.year+' · '+b.primaryEnergy+' kWh/m²/year · '+b.co2+' kgCO₂/m²/year</p><p>'+b.recommendations.map(esc).join('<br>')+'</p><p>This will open a profile review with example dwelling facts. Saving labels the home synthetic. A real certificate is still required.</p></div>','<div class="modal-footer"><button class="outline-btn" data-action="close-modal">Cancel</button><button class="primary-btn" id="review-ber">Review example facts</button></div>');
 $('#review-ber').onclick=()=>homeForm(false,{type:b.type,area:b.area,year:b.year,occupiedYear:b.year,ber:b.rating,heating:b.heating,walls:b.walls,attic:b.attic,traditional:b.year<1940?'yes':'no',berRecordId:b.id,evidence:[],synthetic:true});
 }if(f.id==='home-form'){const isNew=f.dataset.new==='true',data={...(!isNew?state.profile.data:{consent:false,synthetic:false}),...Object.fromEntries(form),evidence:form.getAll('evidence')};data.berRecordId=f.dataset.ber||'';if(data.berRecordId)data.synthetic=true;for(const k of ['year','occupiedYear','area','budget'])data[k]=Number(data[k]);if(isNew){const p=await api('/profiles','POST',data);state.profile=p;await loadProfiles();}else await saveProfile(data);closeModal();render();toast('Your home profile and pathway have been saved.');}if(f.id==='chat-form'){if(state.busy)return;const message=form.get('message'),chatProfileId=state.profile.id;state.drafts[chatProfileId]=message;state.busy=true;render();try{await api(`/profiles/${chatProfileId}/interview`,'POST',{message});state.drafts[chatProfileId]='';state.messages=(await api(`/profiles/${state.profile.id}/messages`)).messages;}finally{state.busy=false;render();}}if(f.id==='source-search'){const target=$('#search-results');target.textContent='Finding relevant source evidence…';const result=await api('/sources/search','POST',{query:form.get('query')});target.innerHTML=`<p class="tiny">${result.mode==='vector'?'Semantic vector':'Keyword'} retrieval · ${result.chunks.length} excerpts. Source excerpts are evidence, not a decision on your eligibility.</p>${result.chunks.map(c=>`<article class="search-result"><strong>${esc(c.title)}</strong><p>${esc(c.body)}</p><a href="${esc(c.url)}" target="_blank" rel="noopener">SEAI source · checked ${date(c.checked_at)} ${icon('external')}</a></article>`).join('')}`;}if(f.id==='invite-form'){const r=await api('/admin/invites','POST',Object.fromEntries(form));$('#invite-result').innerHTML=`<div class="notice info"><p>Invitation created. Share this single-use link securely. No email has been sent.</p></div><label class="form-field"><span>Invitation link</span><input readonly value="${esc(r.url)}" aria-label="Invitation link"/></label>`;f.reset();}if(f.id==='retention-form'){const v={retentionDays:Number(form.get('retentionDays')),auditRetentionDays:Number(form.get('auditRetentionDays'))};await api('/admin/settings','PUT',v);state.session.retentionDays=v.retentionDays;state.session.auditRetentionDays=v.auditRetentionDays;toast('Retention policy saved and audited.');}if(f.id==='assignment-form'){await api('/admin/assignments','PUT',{profileId:form.get('profileId'),adviserId:form.get('adviserId')||null});await loadProfiles();await loadPage('governance');toast('Adviser access updated.');}}catch(e){const error=f.querySelector('.form-error');if(error&&f.isConnected)error.textContent=e.message;else toast(e.message);}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('keydown',e=>{const m=$('.modal');if(!m)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=[...m.querySelectorAll('button:not([disabled]),input:not([disabled]),select,textarea,a[href],summary')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{if(!state.session?.user||!location.hash||location.hash==='#home'){render();return;}const page=location.hash.slice(1)||'overview';if(!['overview','interview','pathway','compare','funding','reports','sources','privacy','governance'].includes(page))return;if(page==='governance'&&state.session.user.role!=='admin')return go('overview');loadPage(page).catch(e=>toast(e.message));});
async function boot(){try{state.session=await api('/session');if(state.session.user){await loadProfiles();const page=location.hash.slice(1)||'overview';await loadPage(page==='governance'&&state.session.user.role!=='admin'?'overview':page);}else render();}catch(e){$('#app').innerHTML=`<div class="boot">We couldn’t open the workspace.<span>${esc(e.message)}</span><button class="outline-btn mt20" id="retry-boot">Try again</button></div>`;$('#retry-boot').onclick=boot;}}
boot();
